pub fn adaptive_sort<T: Ord>(arr: &mut [T]) {
    let n = arr.len();
    if n <= 1 { return; }
    if n <= 24 || is_nearly_sorted(arr, 0.02) { insertion_sort(arr); }
    else { arr.sort_unstable(); }
}

// Helper function to detect if array is nearly sorted
fn is_nearly_sorted<T: Ord>(arr: &[T], threshold: f64) -> bool {
    let n = arr.len();
    if n <= 1 { return true; }
    let limit = ((n as f64) * threshold) as usize;
    let limit = limit.max(1);
    let mut bad = 0usize;
    for i in 1..n {
        if arr[i - 1] > arr[i] {
            bad += 1;
            if bad > limit { return false; }
        }
    }
    true
}

// Helper function for insertion sort (useful for small arrays)
fn insertion_sort<T: Ord>(arr: &mut [T]) {
    for i in 1..arr.len() {
        let mut j = i;
        while j > 0 && arr[j - 1] > arr[j] {
            arr.swap(j, j - 1);
            j -= 1;
        }
    }
}
